import {
  Timestamps2
} from "../chunks/repository-cache-qfa1cgps.js";

// src/account/sql.ts
import { sqliteTable, text, integer, primaryKey } from "drizzle-orm/sqlite-core";
var AccountTable = sqliteTable("account", {
  id: text().primaryKey(),
  email: text().notNull(),
  url: text().notNull(),
  access_token: text().notNull(),
  refresh_token: text().notNull(),
  token_expiry: integer(),
  ...Timestamps2
});
var AccountStateTable = sqliteTable("account_state", {
  id: integer().primaryKey(),
  active_account_id: text().references(() => AccountTable.id, { onDelete: "set null" }),
  active_org_id: text()
});
var ControlAccountTable = sqliteTable("control_account", {
  email: text().notNull(),
  url: text().notNull(),
  access_token: text().notNull(),
  refresh_token: text().notNull(),
  token_expiry: integer(),
  active: integer({ mode: "boolean" }).notNull().$default(() => false),
  ...Timestamps2
}, (table) => [primaryKey({ columns: [table.email, table.url] })]);
export {
  AccountStateTable,
  AccountTable,
  ControlAccountTable
};
